<script dangerouslySetInnerHTML={{__html:"\r\n    (function(){\r\n      'use strict';\r\n      var SHEET='/api/forms/book-demo';\r\n      var MN=['January','February','March','April','May','June','July','August','September','October','November','December'];\r\n      var today=new Date(), sel=null, vy=today.getFullYear(), vm=today.getMonth();\r\n      var lbl=document.getElementById('wdCalMonth'), grd=document.getElementById('wdCalGrid');\r\n      var frm=document.getElementById('wdBookDemoForm');\r\n      if(!lbl||!grd||!frm)return;\r\n      var btnT=document.getElementById('wdBtnText'), btnL=document.getElementById('wdBtnLoader');\r\n      var btnS=document.getElementById('wdSubmitBtn'), sts=document.getElementById('wdStatus');\r\n      function fmtISO(d){return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate());}\r\n      function pad(n){return String(n).padStart(2,'0');}\r\n      function fmtD(d){return d.toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'});}\r\n      function same(a,b){return a&&b&&a.getFullYear()===b.getFullYear()&&a.getMonth()===b.getMonth()&&a.getDate()===b.getDate();}\r\n      function isPast(d){var n=new Date();n.setHours(0,0,0,0);return new Date(d.getFullYear(),d.getMonth(),d.getDate())<n;}\r\n      var B='display:flex;align-items:center;justify-content:center;width:100%;min-height:34px;height:34px;border-radius:8px;font-size:14px;font-weight:500;color:#042a2b;background:transparent;border:1px solid transparent;cursor:pointer;box-sizing:border-box;padding:0;line-height:1;';\r\n      var P=B.replace('color:#042a2b','color:rgba(192,57,43,0.65)').replace('background:transparent','background:rgba(239,68,68,0.08)')+'text-decoration:line-through;cursor:not-allowed;';\r\n      var T=B.replace('color:#042a2b','color:#0a6060').replace('border:1px solid transparent','border:1px solid rgba(84,242,242,0.6)')+'font-weight:700;';\r\n      var S=B.replace('color:#042a2b','color:#042a2b').replace('background:transparent','background:#54f2f2').replace('border:1px solid transparent','border:1px solid #54f2f2')+'font-weight:700;';\r\n      function render(){\r\n        lbl.textContent=MN[vm]+' '+vy;\r\n        lbl.style.cssText='color:#042a2b;font-size:1rem;font-weight:700;';\r\n        grd.style.cssText='display:grid;grid-template-columns:repeat(7,1fr);gap:3px;';\r\n        grd.innerHTML='';\r\n        var fd=new Date(vy,vm,1),sd=fd.getDay(),dim=new Date(vy,vm+1,0).getDate();\r\n        for(var i=0;i<sd;i++){var e=document.createElement('button');e.type='button';e.disabled=true;e.style.cssText=B+'visibility:hidden;pointer-events:none;';grd.appendChild(e);}\r\n        for(var d=1;d<=dim;d++){\r\n          var cd=new Date(vy,vm,d),c=document.createElement('button');\r\n          c.type='button';c.textContent=''+d;\r\n          var ip=isPast(cd),it=same(cd,today),is=sel&&same(cd,sel);\r\n          c.style.cssText=is?S:(it?T:(ip?P:B));\r\n          if(ip){c.disabled=true;}\r\n          else{\r\n            (function(btn,base){btn.addEventListener('mouseenter',function(){btn.style.cssText=base+'background:rgba(84,242,242,0.15);border-color:rgba(84,242,242,0.5);';});btn.addEventListener('mouseleave',function(){btn.style.cssText=base;});})(c,it?T:B);\r\n            (function(date){c.addEventListener('click',function(){pick(date);});})(cd);\r\n          }\r\n          grd.appendChild(c);\r\n        }\r\n      }\r\n      function pick(dt){\r\n        sel=dt;var hd=document.getElementById('wd_date');if(hd)hd.value=fmtISO(dt);\r\n        render();\r\n        var ec=document.getElementById('wdDateEcho'),tx=document.getElementById('wdDateText');\r\n        if(tx)tx.textContent=fmtD(dt);\r\n        if(ec)ec.classList.add('filled');\r\n        if(sts)sts.innerHTML='';\r\n        var sd=document.getElementById('wdCalSelDisplay');\r\n        if(sd)sd.innerHTML='<svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"1.8\" stroke=\"currentColor\" style=\"width:16px;height:16px;flex-shrink:0;color:#54f2f2\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M6.75 3v2.25M17.25 3v2.25M3 18.75V7.5a2.25 2.25 0 012.25-2.25h13.5A2.25 2.25 0 0121 7.5v11.25m-18 0A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75m-18 0v-7.5A2.25 2.25 0 015.25 9h13.5A2.25 2.25 0 0121 11.25v7.5\"/></svg><span>Selected: <strong style=\"color:#0a6060;\">'+fmtD(dt)+'</strong></span>';\r\n      }\r\n      document.getElementById('wdCalPrev').addEventListener('click',function(){vm--;if(vm<0){vm=11;vy--;}render();});\r\n      document.getElementById('wdCalNext').addEventListener('click',function(){vm++;if(vm>11){vm=0;vy++;}render();});\r\n      render();\r\n      // Testimonial slider\r\n      var track=document.getElementById('wdTestiTrack');\r\n      if(track){var idx=0,cards=track.querySelectorAll('.wd-testi-card');\r\n      document.getElementById('wdTestiNext').addEventListener('click',function(){idx=Math.min(idx+1,cards.length-3);track.style.transform='translateX(-'+(idx*(340+24))+'px)';});\r\n      document.getElementById('wdTestiPrev').addEventListener('click',function(){idx=Math.max(idx-1,0);track.style.transform='translateX(-'+(idx*(340+24))+'px)';});}\r\n      // Accordion\r\n      document.querySelectorAll('.wd-acc-header').forEach(function(h){h.addEventListener('click',function(){var item=h.parentElement;item.classList.toggle('open');});});\r\n      // Tabs\r\n      document.querySelectorAll('.wd-tab').forEach(function(tab){tab.addEventListener('click',function(){document.querySelectorAll('.wd-tab').forEach(function(t){t.classList.remove('active');});document.querySelectorAll('.wd-tab-panel').forEach(function(p){p.classList.remove('active');});tab.classList.add('active');var panel=document.getElementById('wdPanel-'+tab.dataset.tab);if(panel)panel.classList.add('active');});});\r\n      // Skill bars animate on scroll\r\n      var bars=document.querySelectorAll('.wd-skill-bar-fill');\r\n      var barObs=new IntersectionObserver(function(entries){entries.forEach(function(e){if(e.isIntersecting)e.target.classList.add('animated');});},{threshold:0.3});\r\n      bars.forEach(function(b){barObs.observe(b);});\r\n      // Scroll reveal\r\n      var reveals=document.querySelectorAll('.wd-reveal');\r\n      var revObs=new IntersectionObserver(function(entries){entries.forEach(function(e){if(e.isIntersecting)e.target.classList.add('visible');});},{threshold:0.1,rootMargin:'0px 0px -40px 0px'});\r\n      reveals.forEach(function(r){revObs.observe(r);});\r\n      // Form submit\r\n      frm.addEventListener('submit',function(e){\r\n        e.preventDefault();\r\n        if(!frm.checkValidity()){frm.reportValidity();return;}\r\n        var hd=document.getElementById('wd_date');\r\n        if(!hd||!hd.value){if(sts)sts.innerHTML='<span class=\"err\">Please select a date from the calendar.</span>';return;}\r\n        if(btnT)btnT.style.display='none';if(btnL)btnL.style.display='inline-block';if(btnS)btnS.disabled=true;\r\n        var fd=new FormData(frm);\r\n        fetch(SHEET,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({name:fd.get('name')||'',phone:fd.get('phone')||'',email:fd.get('email')||'',course:fd.get('course')||'',mode:fd.get('mode')||'',date:hd.value,message:fd.get('message')||'',timestamp:new Date().toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}),source:window.location.href})})\r\n        .then(function(){if(sts)sts.innerHTML='<span class=\"ok\">✓ Booked! We\\'ll confirm within 2 hours.</span>';frm.reset();sel=null;if(hd)hd.value='';var ec=document.getElementById('wdDateEcho');if(ec){ec.classList.remove('filled');var tx=document.getElementById('wdDateText');if(tx)tx.textContent='\\u2190 Pick a date from the calendar';}render();})\r\n        .catch(function(){if(sts)sts.innerHTML='<span class=\"err\">Could not submit. Please try again.</span>';})\r\n        .finally(function(){if(btnT)btnT.style.display='inline';if(btnL)btnL.style.display='none';if(btnS)btnS.disabled=false;});\r\n      });\r\n    })();\r\n    "}} />


